spec.setup_code:
var seed = 7;
function rnd() { seed |= 0; seed = (seed + 0x6D2B79F5) | 0; var t = Math.imul(seed ^ (seed >>> 15), 1 | seed); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }
function gauss() { var u = Math.max(1e-6, rnd()), v = rnd(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(6.2831853 * v); }
var N = 80;
var X0 = [], X1 = [];
for (var i = 0; i < N; i++) {
  X0.push([-1.9 + 0.6 * gauss(), 0.6 * gauss()]);
  var a = rnd() * Math.PI;
  var p;
  if (i % 2 === 0) p = [Math.cos(a), Math.sin(a)];
  else p = [1 - Math.cos(a), 0.5 - Math.sin(a)];
  X1.push([1.9 + 1.2 * (p[0] - 0.5) + 0.07 * gauss(), 1.2 * (p[1] - 0.25) + 0.07 * gauss()]);
}
X0.sort(function (a, b) { return a[1] - b[1]; });
X1.sort(function (a, b) { return a[1] - b[1]; });
var AMP = [];
for (var j = 0; j < N; j++) AMP.push((j % 2 ? 1 : -1) * (0.35 + 0.6 * rnd()));
var INK = '#1a1a1d';
function clamp(x, a, b) { return Math.max(a, Math.min(b, x)); }
function pos(i, t, k) {
  var a = X0[i], b = X1[i];
  var x = (1 - t) * a[0] + t * b[0], y = (1 - t) * a[1] + t * b[1];
  if (k === 1) {
    var dx = b[0] - a[0], dy = b[1] - a[1];
    var L = Math.sqrt(dx * dx + dy * dy) + 1e-6;
    var o = Math.sin(Math.PI * t) * AMP[i] * 0.6;
    x += -dy / L * o * 1.0; y += dx / L * o * 1.0;
  }
  return [x, y];
}
return {
  draw: function (ctx, width, height, time, dt) {
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, width, height);
    var period = 9;
    var tt = time % period;
    var t = clamp((tt - 1) / 6, 0, 1);
    var m = 16;
    var pw = (width - 3 * m) / 2;
    var top = 56;
    var ph = Math.min(height - top - 70, pw * 0.7);
    var titles = ['Flow matching: straight OT paths', 'Diffusion-like paths (schematic)'];
    var cols = ['#7c3aed', '#0284c7'];
    for (var k = 0; k < 2; k++) {
      var ox = m + k * (pw + m), oy = top;
      var sx = pw / 7.2, sy = ph / 4.4;
      var cx = ox + pw / 2, cy = oy + ph / 2;
      var P = function (p) { return [cx + p[0] * sx, cy - p[1] * sy]; };
      ctx.strokeStyle = '#d4d4d8'; ctx.lineWidth = 1;
      ctx.strokeRect(ox, oy, pw, ph);
      ctx.fillStyle = INK; ctx.font = '13px sans-serif'; ctx.textAlign = 'left';
      ctx.fillText(titles[k], ox, oy - 8);
      ctx.font = '12px sans-serif';
      ctx.fillStyle = cols[k];
      ctx.fillText('p_0 = N(0, I)', ox + 8, oy + ph - 8);
      ctx.fillStyle = '#d97706';
      ctx.textAlign = 'right';
      ctx.fillText('data q', ox + pw - 8, oy + ph - 8);
      ctx.textAlign = 'left';
      // faint full paths
      ctx.lineWidth = 1;
      for (var i = 0; i < N; i += 2) {
        ctx.strokeStyle = 'rgba(100,100,110,0.13)';
        ctx.beginPath();
        var q = P(pos(i, 0, k)); ctx.moveTo(q[0], q[1]);
        var S = k === 0 ? 1 : 12;
        for (var s = 1; s <= S; s++) { q = P(pos(i, s / S, k)); ctx.lineTo(q[0], q[1]); }
        ctx.stroke();
      }
      // traversed trails
      ctx.strokeStyle = k === 0 ? 'rgba(124,58,237,0.35)' : 'rgba(2,132,199,0.35)';
      for (var i2 = 0; i2 < N; i2 += 2) {
        ctx.beginPath();
        var q2 = P(pos(i2, 0, k)); ctx.moveTo(q2[0], q2[1]);
        var S2 = k === 0 ? 1 : 12;
        for (var s2 = 1; s2 <= S2; s2++) { q2 = P(pos(i2, t * s2 / S2, k)); ctx.lineTo(q2[0], q2[1]); }
        ctx.stroke();
      }
      // data ghosts
      ctx.strokeStyle = '#d97706'; ctx.lineWidth = 1;
      for (var g = 0; g < N; g++) {
        var d = P(X1[g]);
        ctx.beginPath(); ctx.arc(d[0], d[1], 3.2, 0, 6.2832); ctx.stroke();
      }
      // velocity arrows (flow panel)
      if (k === 0 && t > 0 && t < 1) {
        ctx.strokeStyle = '#059669'; ctx.fillStyle = '#059669'; ctx.lineWidth = 1.5;
        for (var v = 3; v < N; v += 10) {
          var pp = pos(v, t, 0);
          var ux = (X1[v][0] - X0[v][0]) * 0.3, uy = (X1[v][1] - X0[v][1]) * 0.3;
          var a0 = P(pp), a1 = P([pp[0] + ux, pp[1] + uy]);
          ctx.beginPath(); ctx.moveTo(a0[0], a0[1]); ctx.lineTo(a1[0], a1[1]); ctx.stroke();
          var ang = Math.atan2(a1[1] - a0[1], a1[0] - a0[0]);
          ctx.beginPath(); ctx.moveTo(a1[0], a1[1]);
          ctx.lineTo(a1[0] - 6 * Math.cos(ang - 0.4), a1[1] - 6 * Math.sin(ang - 0.4));
          ctx.lineTo(a1[0] - 6 * Math.cos(ang + 0.4), a1[1] - 6 * Math.sin(ang + 0.4));
          ctx.closePath(); ctx.fill();
        }
      }
      // points
      ctx.fillStyle = cols[k];
      for (var n = 0; n < N; n++) {
        var c = P(pos(n, t, k));
        ctx.beginPath(); ctx.arc(c[0], c[1], 3, 0, 6.2832); ctx.fill();
      }
    }
    // time bar
    var bx = m + 30, bw = width - 2 * m - 60, by = top + ph + 30;
    ctx.fillStyle = INK; ctx.font = '12px sans-serif'; ctx.textAlign = 'left';
    ctx.fillText('t', m + 8, by + 4);
    ctx.strokeStyle = '#a1a1aa'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(bx, by); ctx.lineTo(bx + bw, by); ctx.stroke();
    ctx.strokeStyle = '#7c3aed'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(bx, by); ctx.lineTo(bx + bw * t, by); ctx.stroke();
    ctx.fillStyle = '#7c3aed';
    ctx.beginPath(); ctx.arc(bx + bw * t, by, 5, 0, 6.2832); ctx.fill();
    ctx.fillStyle = INK;
    var msg;
    if (t < 0.02) msg = 't = 0.00: x0 ~ N(0, I)';
    else if (t > 0.98) msg = 't = 1.00: φ_1 ≈ samples from q';
    else msg = 't = ' + t.toFixed(2) + ': dφ_t/dt = v_t(φ_t),  x_t = (1−t)x0 + t x1,  u_t = x1 − x0';
    ctx.fillText(msg, bx, by + 24);
    ctx.fillStyle = '#059669';
    ctx.fillText('green arrows: constant velocity u_t', bx, by + 42);
    ctx.fillStyle = INK;
    ctx.font = '13px sans-serif';
    ctx.fillText('Same pairs (x0, x1); flow matching learns v_t ≈ E[u_t | x_t]', m, 22);
  }
};
